public static boolean isIdentical(Queue<Integer> q1, Queue<Integer> q2) {
    int n = size(q1);
    if (n != size(q2)) {
        return false;
    }
    boolean same = true;
    // מסובבים את שני התורים סיבוב שלם: כל איבר יוצא מהראש וחוזר לסוף — כך הם חוזרים להיות כמו בהתחלה
    for (int i = 0; i < n; i++) {
        int a = q1.remove();
        int b = q2.remove();
        if (a != b) {
            same = false;
        }
        q1.insert(a);
        q2.insert(b);
    }
    return same;
}

public static boolean isSimilar(Queue<Integer> q1, Queue<Integer> q2) {
    if (isIdentical(q1, q2)) {
        return true;
    }
    int n = size(q1);
    // כל "העברה מההתחלה לסוף" נותנת סדר אחר; אחרי n העברות התור חוזר להיות כמו בהתחלה
    for (int i = 1; i < n; i++) {
        q1.insert(q1.remove());
        if (isIdentical(q1, q2)) {
            return true;
        }
    }
    return false;
}

