public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

// הפעולה הנתונה בשאלה: מספר האיברים בתור q, בלי לשנות את התור
public static int size(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int count = 0;
    while (!q.isEmpty()) {
        temp.insert(q.remove());
        count++;
    }
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return count;
}

// תור עם הערכים לפי הסדר (הראשון — בראש התור)
public static Queue<Integer> build(int[] values) {
    Queue<Integer> q = new Queue<Integer>();
    for (int i = 0; i < values.length; i++) {
        q.insert(values[i]);
    }
    return q;
}

