Queue<Integer> q1 = build(new int[] { 6, 2, 8, 9 });
Queue<Integer> q2 = build(new int[] { 6, 2, 8, 9 });
System.out.println("סעיף א, בדיקה 1 (הדוגמה — זהים): " + check(isIdentical(q1, q2), true));
System.out.println("סעיף א, בדיקה 2 (שני התורים נשארו כמו בהתחלה): " + check(q1 + " " + q2, "[6,2,8,9] [6,2,8,9]"));
System.out.println("סעיף א, בדיקה 3 (אותם ערכים, סדר אחר): " + check(isIdentical(build(new int[] { 6, 2, 9 }), build(new int[] { 6, 9, 2 })), false));
System.out.println("סעיף א, בדיקה 4 (מספר איברים שונה): " + check(isIdentical(build(new int[] { 6, 2 }), build(new int[] { 6, 2, 8 })), false));
System.out.println("סעיף א, בדיקה 5 (שני תורים ריקים): " + check(isIdentical(new Queue<Integer>(), new Queue<Integer>()), true));
System.out.println("סעיף ב, בדיקה 1 (הדוגמה — שתי העברות): " + check(isSimilar(build(new int[] { 4, 6, 5, 7 }), build(new int[] { 5, 7, 4, 6 })), true));
System.out.println("סעיף ב, בדיקה 2 (אותם ערכים, אבל לא בסיבוב): " + check(isSimilar(build(new int[] { 1, 2, 3 }), build(new int[] { 1, 3, 2 })), false));
System.out.println("סעיף ב, בדיקה 3 (מספר איברים שונה): " + check(isSimilar(build(new int[] { 1, 2 }), build(new int[] { 1, 2, 1 })), false));

